(7442795, 1177021, 150277, '<td valign="top">Struggling to feel a mood with this one.</td>', 'Struggling to feel a mood with this one.', '2016-03-10 13:11:12.000000', NULL, 1),
(7442796, 1176994, 150277, '<td valign="top">Not getting a clear feeling with this one.</td>', 'Not getting a clear feeling with this one.', '2016-03-10 13:11:36.000000', NULL, 1),
(7442799, 1176983, 150277, '<td valign="top">I like the image, but I''m not getting any strong feeling of mood.  Wish I were seeing maybe some empty cans on their side or something to bring in some context.  Just a can opening is not provoking any feeling with me.</td>', 'I like the image, but I''m not getting any strong feeling of mood.  Wish I were seeing maybe some empty cans on their side or something to bring in some context.  Just a can opening is not provoking any feeling with me.', '2016-03-10 13:12:49.000000', NULL, 1),
